#!/usr/bin/env bash
# scripts/cpu-lock.sh COMMAND... — run a TIMING-DEPENDENT job (benchmarks, real-time factor, latency)
# holding the CPU lock shared with other agent sessions on this machine. Protocol:
# docs/agents/agent-orchestration.md § "Exclusive CPU between sessions". Builds/tests never use it.
# Do not edit this file while a job runs through it (a shell reads its script as it runs).
D=/tmp/claude-$(id -u); LOCK=$D/cpu-heavy.lock; OWNER=$D/cpu-heavy.owner
mkdir -p "$D"
session_pid() {  # the agent session (nearest `claude` ancestor), or the parent shell if none
  p=$$; while [ "$p" -gt 1 ]; do [ "$(cat /proc/$p/comm 2>/dev/null)" = claude ] && { echo $p; return; }
    p=$(awk '{print $4}' /proc/$p/stat 2>/dev/null || echo 1); done; echo $PPID
}
alive() { case "$1" in ""|*[!0-9]*) return 0;; esac; kill -0 "$1" 2>/dev/null; }
exec 9>"$LOCK"
waited=0
until flock -n 9; do
  read -r hpid _ spid _ < "$OWNER" 2>/dev/null
  if [ -n "$hpid" ] && { ! alive "$hpid" || ! alive "$spid"; }; then
    echo "[cpu-lock] holder orphaned; stopping it: $(cat "$OWNER" 2>/dev/null)" >&2
    alive "$hpid" && { kill -TERM "$hpid"; sleep 15; kill -KILL "$hpid" 2>/dev/null; }
    flock -w 120 9 && break
    echo "[cpu-lock] still held; giving up" >&2; exit 75
  fi
  if [ $waited -ge 1800 ]; then
    # 30 min: allowed to stop the holder; we choose to go ahead niced instead (agreed with the peer).
    echo "[cpu-lock] waited 30 min; running niced without the lock" >&2
    exec nice -n 19 timeout 1800 "$@"
  fi
  sleep 30; waited=$((waited + 30))
done
echo "$$ engine-sim $(session_pid) $(date +%FT%T) $*" > "$OWNER"
timeout 1800 "$@"; rc=$?
: > "$OWNER"; exit $rc
